%% Bero potentziaren kalkuluafunction [hasierakoK,l,limK,y,paso,kontador]=grafikoa6(a,b,Sp,Sn,Rp,Rn,Tdif,N,Ap,An,Lp,Ln,Ep,En,izena,j,p,r1,y1,r2,y2,r3,y3,r4,y4,r5,y5,r6,y6,Ti,opt,kontador)  n=300;    x=linspace(a,b,n+1);##  lim=25;##  j=(Tdif-lim)/p;  if opt==1  for k=0:j  numeros=[(Tdif-p*k)+Ti,Ti];  T_b=mean(numeros);    Sp_b=aurkitu(T_b,r1,y1)    Sn_b=aurkitu(T_b,r2,y2)    Rp_b=aurkitu(T_b,r3,y3)    Rn_b=aurkitu(T_b,r4,y4)   Kp_b=aurkitu(T_b,r5,y5)   Kn_b=aurkitu(T_b,r6,y6)    f=@(x) (x*(Sp_b+Sn_b)*((Tdif)+Ti)-0.5*x.^2*(Lp*Rp_b/Ap+Ln*Rn_b/An)+(Kp_b*Ap/Lp+Kn_b*An/Ln)*(Tdif))*N;    if isa(f,'function_handle')==1      F=f(x);      else      F=f;      end      figure((k+1)+kontador)      plot(x,F)      xlabel('I (A)')      ylabel('Q_{out} (W)')       aldagaibalioa=num2str(Tdif-p*k)     limK=40     paso=5     hasierakoK=2     l=(limK-hasierakoK)/paso     l=round(l)     for v=1:l     korrontea(v)=hasierakoK+(paso*(v-1))      end      for w=1:l         h=w+(k*l);      Bero_Potentzia(h)=aurkitu(korrontea(w),x,F)      end      title(["La curva del calor que se transfiere en el material termoelectrico a este gradiente de temperatura:",aldagaibalioa])      legend(izena,'Location','southoutside')      legend('boxoff')      grid on      hold on            end      else      for k=0:j    T_prop=T_prop=(T_hot-T_cold)/log(T_hot/T_cold) ;    Sp_prop=aurkitu(T_prop,r1,y1)    Sn_prop=aurkitu(T_prop,r2,y2)    Rp_prop=aurkitu(T_prop,r3,y3)    Rn_prop=aurkitu(T_prop,r4,y4)   Kp_prop=aurkitu(T_prop,r5,y5)   Kn_prop=aurkitu(T_prop,r6,y6)    f=@(x) (x*(Sp_prop+Sn_prop)*((Tdif)+Ti)-0.5*x.^2*(Lp*Rp_prop/Ap+Ln* Rn_prop/An)+(Kp_prop*Ap/Lp+Kn_prop*An/Ln)*(Tdif))*N;    if isa(f,'function_handle')==1      F=f(x);      else      F=f;      end      figure(k+kontador)      plot(x,F)      xlabel('I (A)')      ylabel('Q_{out} (W)')       aldagaibalioa=num2str(Tdif-p*i)    limK=40     paso=5     hasierakoK=2     l=(limK-hasierakoK)/paso     l=round(l)     for v=1:l     korrontea(v)=hasierakoK+(paso*(v-1))      end      for w=1:l        h=w+(k*l);      Bero_Potentzia(h)=aurkitu(korrontea(w),x,F)      end      title(["La curva del calor que se transfiere en el material termoelectrico a este gradiente de temperatura:",aldagaibalioa])      legend(izena,'Location','southoutside')      legend('boxoff')      grid on      end      end      hasierakoK=hasierakoK;      l=l;      limK=limK;      y=Bero_Potentzia;      paso=paso;      kontador=(k+1)+kontador;     ##  print(figure(13),'TFGdif12')##  print(figure(14),'TFGdif13')##  print(figure(15),'TFGdif14')##  print(figure(16),'TFGdif15')##  print(figure(17),'TFGdif16')##  print(figure(18),'TFGdif17')##  print(figure(19),'TFGdif18')##  print(figure(20),'TFGdif19')##  print(figure(21),'TFGdif20')##  print(figure(22),'TFGdif21')endfunction